module.exports = function (L) {
  const master = {
    id: 'master', level: 'Master', badge: '👑 Grandmaster', title: 'Section 4: Master Architecture',
    description: 'Peek inside React Fiber, master advanced component patterns, and design modern server-first architecture at scale.',
    lessons: [
      L({
        id: 'react-mst-1', number: '10', title: 'React Fiber Internals: Double Buffering, Diffing & Concurrent Rendering', duration: '55 min', xp: 450,
        summary: 'Learn how React represents your UI as a Fiber tree, diffs it in O(n), and keeps the UI responsive with concurrent features.',
        mm: { title: 'The Architect with Two Blueprints', analogy: 'React keeps two blueprints of your building: the one currently on display (current tree) and a draft being edited in the back room (work-in-progress tree). The draft can be paused when an urgent visitor arrives, then resumed. Only when it is finished does React swap the draft onto the display in one quick commit.', keyInsight: 'Rendering (building the draft) is interruptible and pure; committing (touching the real DOM) is synchronous and short.' },
        theory: [
          ['Fiber nodes and double buffering', '<p>Each element becomes a <strong>Fiber</strong>: a plain object with <code>type</code>, <code>props</code>, <code>memoizedState</code> (the hooks list), and links <code>child</code>, <code>sibling</code> and <code>return</code>. React holds a <code>current</code> tree and builds a <code>workInProgress</code> tree by reusing/cloning fibers (each fiber has an <code>alternate</code>). After the render phase completes, a single pointer swap makes the draft the new current tree.</p>', 'function App() {\n  const [n, setN] = useState(0);   // stored on App\'s fiber.memoizedState\n  return <button onClick={() => setN(n + 1)}>{n}</button>;\n}\n// Fiber(App) -> child Fiber(button) -> child Fiber(text)', ['Phase', 'Does', 'Interruptible'], [['Render', 'Calls components, diffs, builds draft', 'Yes (concurrent)'], ['Commit', 'Mutates DOM, runs layout effects', 'No'], ['Passive effects', 'Runs useEffect', 'After paint']]],
          ['Diffing heuristics', '<p>Comparing two arbitrary trees is O(n³). React uses two assumptions to get O(n): (1) elements of <strong>different types</strong> produce different trees, so React unmounts the old subtree and mounts a new one; (2) a <strong>key</strong> hints which children are stable across renders. Same type means React keeps the instance and state, and just updates props.</p>', '// Type changes -> state is DESTROYED\n{ isAdmin ? <AdminPanel /> : <UserPanel /> }\n// Same type + same position -> state PRESERVED\n<Input key={userId} />   // changing key forces a fresh instance', ['Situation', 'React does'], [['Same type', 'Update props, keep state'], ['Different type', 'Unmount + remount'], ['Key changes', 'Remount that child'], ['Same key reordered', 'Move DOM node']]],
          ['Concurrent rendering: transitions', '<p>Concurrent rendering lets React work on updates in slices and prioritise urgent ones. <code>useTransition</code> marks a state update as non-urgent so typing stays responsive while a heavy list re-renders. <code>useDeferredValue</code> gives you a lagging copy of a value for the same purpose.</p>', 'function Search({ items }) {\n  const [q, setQ] = useState("");\n  const [isPending, startTransition] = useTransition();\n  const [filter, setFilter] = useState("");\n  return (\n    <>\n      <input value={q} onChange={e => { setQ(e.target.value); startTransition(() => setFilter(e.target.value)); }} />\n      {isPending && <span>Updating...</span>}\n      <List items={items} filter={filter} />\n    </>\n  );\n}', ['API', 'Use for'], [['useTransition', 'Mark updates as non-urgent'], ['useDeferredValue', 'Lagging copy of a value'], ['Suspense', 'Show fallback while waiting']]]
        ],
        pitfalls: [['Defining a component inside another component', 'Every parent render creates a new function type, so React remounts the child and loses its state.', 'Define components at module level and pass data via props.'], ['Using `Math.random()` as a key', 'A different key every render forces remounts of the whole list.', 'Use a stable id from your data.']],
        take: ['Fibers are the units of work forming a linked tree.', 'Render is interruptible; commit is atomic.', 'Different type or key means remount; same means update.', 'Transitions keep urgent interactions responsive.'],
        simType: 'react-fiber-sim', simTitle: 'Current vs Work-In-Progress Fiber Trees',
        steps: [
          ['Initial mount', 'root.render(<App />)', 'React builds the first Fiber tree and commits it as current.', [['current', 'App → button', 'fiber']], [['App fiber', 'state n = 0']], ''],
          ['State update', 'setN(1)', 'An update is scheduled on App\'s fiber with a priority lane.', [['pending', 'n: 0 → 1', 'update']], [['App fiber', 'queue: +1']], ''],
          ['Render phase', 'beginWork(App)', 'React clones fibers into a work-in-progress tree and re-runs App; it can pause here.', [['workInProgress', 'App → button(1)', 'fiber']], [['WIP tree', 'text "1"']], 'Render pure, no DOM yet'],
          ['Commit phase', 'commitRoot()', 'The pointer swaps and the single text node is updated in the DOM.', [['current', 'App → button(1)', 'fiber']], [['DOM', 'button text = 1']], 'DOM updated']
        ],
        presets: [['Key reset', 'Change key to remount', '<Form key={id} />', 'State resets'], ['Transition', 'Defer heavy update', 'startTransition(() => set(v))', 'Input stays snappy']],
        pg: { title: 'Preserve vs Reset State', mission: 'Add a `key` to `<Profile>` using userId so state resets per user, and log "keyed by 7".', starter: 'function Profile({ userId }) { return <p>User {userId}</p>; }\nfunction App() {\n  const userId = 7;\n  console.log("keyed by", userId);\n  return <Profile userId={userId} />;\n}', solution: 'function Profile({ userId }) { return <p>User {userId}</p>; }\nfunction App() {\n  const userId = 7;\n  console.log("keyed by", userId);\n  return <Profile key={userId} userId={userId} />;\n}', out: 'keyed by 7', hints: ['key goes on the element you want to reset.', 'Use the stable userId value.', '<Profile key={userId} ... />'], req: ['key={userId}'], contains: ['keyed by 7'] },
        bug: { title: 'Disappearing Input Text', prompt: 'Typed text vanishes on every parent re-render. Why?', code: 'function Page() {\n  const [c, setC] = useState(0);\n  function Field() { return <input />; }\n  return <><button onClick={() => setC(c+1)}>+</button><Field /></>;\n}', opts: [['Field is redefined every render, so its type changes and it remounts', 'Correct! Move Field outside Page.'], ['inputs cannot hold state', 'DOM inputs hold their own text.'], ['useState is misused', 'It is used correctly.']], ok: 0 },
        quiz: [['Why is React diffing O(n)?', ['It uses hashing', 'It assumes different types give different trees and uses keys', 'It skips the DOM', 'It uses workers'], 1, 'Two heuristics avoid the general tree-edit problem.'], ['Which phase is interruptible?', ['Commit', 'Render', 'Layout effects', 'Paint'], 1, 'Render is pure and can be paused or restarted.'], ['What does useTransition do?', ['Animates CSS', 'Marks updates as lower priority', 'Caches data', 'Creates refs'], 1, 'It lets urgent updates interrupt non-urgent ones.']]
      }),
      L({
        id: 'react-mst-2', number: '11', title: 'Advanced Patterns: Compound Components, Portals, Error Boundaries & External Stores', duration: '50 min', xp: 450,
        summary: 'Build flexible component APIs and handle edge cases with portals, error boundaries and useSyncExternalStore.',
        mm: { title: 'The LEGO Set with Hidden Wiring', analogy: 'Compound components are like a LEGO kit where the Tabs piece and Tab pieces are designed to snap together — the parent secretly wires them with shared state so you only arrange the pieces. A portal is a teleporter: the piece belongs to its parent logically but appears elsewhere on the table. An error boundary is a fuse box that stops one blown circuit from darkening the whole house.', keyInsight: 'Great component APIs expose composition, not configuration; shared state flows through context behind the scenes.' },
        theory: [
          ['Compound components with context', '<p>Instead of a giant props object, expose related components that share implicit state via context: <code>&lt;Tabs&gt;&lt;Tabs.List&gt;…</code>. The parent owns the state, children consume it. Consumers can reorder or wrap pieces freely.</p>', 'const TabsCtx = createContext(null);\nfunction Tabs({ children, defaultId }) {\n  const [id, setId] = useState(defaultId);\n  return <TabsCtx.Provider value={{ id, setId }}>{children}</TabsCtx.Provider>;\n}\nfunction Tab({ tabId, children }) {\n  const { id, setId } = useContext(TabsCtx);\n  return <button aria-selected={id === tabId} onClick={() => setId(tabId)}>{children}</button>;\n}\nTabs.Tab = Tab;', ['Approach', 'Flexibility'], [['Config props', 'Rigid'], ['Compound components', 'Flexible, declarative']]],
          ['Portals and Error Boundaries', '<p><code>createPortal(children, domNode)</code> renders children into another DOM node (modals, tooltips) while keeping React tree behaviour such as context and event bubbling. <strong>Error boundaries</strong> are class components with <code>getDerivedStateFromError</code> and/or <code>componentDidCatch</code>; they catch errors during rendering of their descendants (not in event handlers or async code).</p>', 'class Boundary extends React.Component {\n  state = { error: null };\n  static getDerivedStateFromError(error) { return { error }; }\n  componentDidCatch(err, info) { console.error(err, info.componentStack); }\n  render() { return this.state.error ? <p>Something broke.</p> : this.props.children; }\n}\nfunction Modal({ children }) { return createPortal(<div className="modal">{children}</div>, document.body); }', ['Tool', 'Catches / Does'], [['Portal', 'Render elsewhere in DOM'], ['Error boundary', 'Render-time errors of children'], ['try/catch', 'Event handlers, async']]],
          ['useSyncExternalStore', '<p>To subscribe to non-React state (a store, <code>window.matchMedia</code>, <code>navigator.onLine</code>) safely under concurrent rendering, use <code>useSyncExternalStore(subscribe, getSnapshot)</code>. It prevents tearing — different parts of the UI showing different values from the same store in a single render. <code>getSnapshot</code> must return a cached/stable value.</p>', 'function useOnline() {\n  return useSyncExternalStore(\n    (cb) => { window.addEventListener("online", cb); window.addEventListener("offline", cb); return () => { window.removeEventListener("online", cb); window.removeEventListener("offline", cb); }; },\n    () => navigator.onLine\n  );\n}', ['Argument', 'Rule'], [['subscribe', 'Returns unsubscribe'], ['getSnapshot', 'Stable, cheap value'], ['getServerSnapshot', 'For SSR']]]
        ],
        pitfalls: [['Expecting an error boundary to catch errors in onClick', 'Boundaries only handle errors thrown during render/lifecycle.', 'Use try/catch in handlers and set error state.'], ['Returning a new object from `getSnapshot` each call', 'React sees a changed snapshot every time and loops infinitely.', 'Return a cached/primitive value.']],
        take: ['Compound components share state through context.', 'Portals change where DOM goes, not where React logic lives.', 'Error boundaries catch render-phase errors.', 'useSyncExternalStore avoids tearing for external state.'],
        simType: 'react-fiber-sim', simTitle: 'Error Boundary Containment',
        steps: [
          ['Normal render', '<Boundary><Widget/></Boundary>', 'The boundary renders its children normally.', [['Boundary.error', 'null', 'state']], [['Widget', 'ok']], ''],
          ['Child throws', 'throw new Error("boom")', 'Widget throws during render; React unwinds to the nearest boundary.', [['Boundary.error', 'Error: boom', 'state']], [['Widget', 'crashed']], 'Render error caught'],
          ['Fallback', 'getDerivedStateFromError', 'The boundary renders its fallback instead of the broken subtree.', [['Boundary.error', 'Error: boom', 'state']], [['Fallback UI', 'Something broke.']], 'Something broke.'],
          ['App survives', 'Rest of page', 'Siblings outside the boundary keep working.', [['Boundary.error', 'Error: boom', 'state']], [['Header', 'still interactive']], 'Contained']
        ],
        presets: [['Portal', 'Modal into body', 'createPortal(<Modal/>, document.body)', 'DOM outside root, same React tree'], ['Reset', 'Retry button', 'setState({ error: null })', 'Re-renders children']],
        pg: { title: 'Compound Toggle', mission: 'Use context so `Toggle.On` renders only when on. Log "state: on" after calling the setter logic.', starter: 'const ToggleCtx = React.createContext(null);\nfunction Toggle({ children }) {\n  const [on, setOn] = React.useState(true);\n  console.log("state:", on ? "on" : "off");\n  // provide { on, setOn } to children\n  return children;\n}\nToggle.On = function On({ children }) {\n  const ctx = React.useContext(ToggleCtx);\n  return ctx.on ? children : null;\n};', solution: 'const ToggleCtx = React.createContext(null);\nfunction Toggle({ children }) {\n  const [on, setOn] = React.useState(true);\n  console.log("state:", on ? "on" : "off");\n  return <ToggleCtx.Provider value={{ on, setOn }}>{children}</ToggleCtx.Provider>;\n}\nToggle.On = function On({ children }) {\n  const ctx = React.useContext(ToggleCtx);\n  return ctx.on ? children : null;\n};', out: 'state: on', hints: ['Wrap children in a Provider.', 'Pass an object with on and setOn.', '<ToggleCtx.Provider value={{ on, setOn }}>'], req: ['ToggleCtx.Provider'], contains: ['state: on'] },
        bug: { title: 'Infinite Store Loop', prompt: 'The component re-renders forever. Why?', code: 'useSyncExternalStore(subscribe, () => ({ width: window.innerWidth }));', opts: [['getSnapshot returns a new object every call', 'Correct! Return a primitive or cached object.'], ['subscribe is missing', 'It is passed.'], ['window is undefined', 'Not the cause here.']], ok: 0 },
        quiz: [['What do compound components share?', ['Props only', 'Implicit state via context', 'Global variables', 'Refs only'], 1, 'The parent provides state through context.'], ['Do error boundaries catch event handler errors?', ['Yes', 'No', 'Only in production', 'Only async'], 1, 'Handlers are outside rendering; use try/catch.'], ['Why useSyncExternalStore?', ['Faster CSS', 'Prevent tearing with external state', 'Replace useState', 'Cache fetches'], 1, 'It keeps all components consistent with one snapshot.']]
      }),
      L({
        id: 'react-mst-3', number: '12', title: 'Modern React Architecture: Server Components, Suspense Streaming & State at Scale', duration: '60 min', xp: 500,
        summary: 'Design applications with Server/Client boundaries, streaming Suspense, optimistic UI and a scalable folder and state strategy.',
        mm: { title: 'The Kitchen and the Dining Table', analogy: 'Server Components are the kitchen: heavy work, secret recipes (database, secrets) and no interactivity; only the finished dish (serialized UI) is sent out. Client Components are the dining table: interactive, with salt shakers (state, events). Suspense streaming is the waiter bringing starters while the main course is still cooking.', keyInsight: 'Default to Server Components; add "use client" only at the leaves that need state, effects or browser APIs.' },
        theory: [
          ['Server vs Client Components', '<p>Server Components run only on the server: they can be <code>async</code>, read databases directly and add <strong>zero JavaScript</strong> to the bundle. Client Components (marked with <code>"use client"</code>) hydrate in the browser and can use state, effects and event handlers. A Server Component can import Client Components and pass serializable props; a Client Component cannot import a Server Component, but can receive one as <code>children</code>.</p>', '// app/page.jsx  (Server Component)\nimport LikeButton from "./LikeButton";\nexport default async function Page() {\n  const post = await db.posts.get(1);        // runs on server only\n  return <article><h1>{post.title}</h1><LikeButton id={post.id} /></article>;\n}\n// LikeButton.jsx\n"use client";\nexport default function LikeButton({ id }) { const [n, setN] = useState(0); return <button onClick={() => setN(n+1)}>{n}</button>; }', ['Capability', 'Server', 'Client'], [['async/await data', 'Yes', 'Via libraries'], ['useState/useEffect', 'No', 'Yes'], ['Browser APIs', 'No', 'Yes'], ['Adds to JS bundle', 'No', 'Yes']]],
          ['Suspense streaming & optimistic UI', '<p><code>&lt;Suspense fallback&gt;</code> lets slow parts of the page load independently: the server streams the shell instantly, then streams each boundary as its data resolves. For mutations, <code>useOptimistic</code> shows the expected result immediately and reconciles with the server response; <code>useActionState</code>/form actions simplify submissions.</p>', 'export default function Page() {\n  return (\n    <>\n      <Header />\n      <Suspense fallback={<Skeleton />}>\n        <Comments />   {/* async Server Component streams in later */}\n      </Suspense>\n    </>\n  );\n}\nconst [optimisticTodos, addOptimistic] = useOptimistic(todos, (s, t) => [...s, { ...t, pending: true }]);', ['Technique', 'Benefit'], [['Suspense boundaries', 'Progressive streaming'], ['useOptimistic', 'Instant perceived feedback'], ['Server Actions', 'Mutations without API glue']]],
          ['State architecture & folder structure at scale', '<p>Classify state before choosing a tool: <strong>server cache</strong> (data from APIs — use TanStack Query/RSC), <strong>URL state</strong> (filters, pagination — use the router), <strong>local UI state</strong> (<code>useState</code>), <strong>shared client state</strong> (context/Zustand), and <strong>form state</strong>. Organise code by feature (<code>features/cart/{components,hooks,api}</code>), keep shared primitives in <code>ui/</code>, and expose each feature through a single public entry file.</p>', 'src/\n  features/\n    cart/ { components/, hooks/, api.js, index.js }\n    auth/ { ... }\n  ui/ { Button.jsx, Modal.jsx }\n  app/ { routes, providers }', ['State kind', 'Best home'], [['Server data', 'RSC / query cache'], ['Filters', 'URL'], ['Toggle open', 'useState'], ['Cross-page shared', 'Context / store']]]
        ],
        pitfalls: [['Marking a whole page "use client"', 'Everything below ships JavaScript and loses server-only benefits.', 'Keep pages as Server Components; push "use client" down to interactive leaves.'], ['Putting all server data in global client state', 'It duplicates the source of truth and causes stale data.', 'Fetch on the server or use a query cache; keep client state for UI only.']],
        take: ['Default to Server Components; use "use client" only at interactive leaves.', 'Suspense boundaries stream slow content progressively.', 'useOptimistic gives instant feedback while mutations settle.', 'Choose state tools by state category, and organise by feature.'],
        simType: 'react-fiber-sim', simTitle: 'Streaming a Page with Suspense',
        steps: [
          ['Request', 'GET /post/1', 'The server starts rendering the Server Component tree.', [['request', 'GET /post/1', 'http']], [['Shell', 'rendering']], ''],
          ['Shell flush', 'Header + Skeleton', 'The static shell and Suspense fallback stream to the browser immediately.', [['stream', 'chunk 1', 'html']], [['Browser', 'Header + <Skeleton/>']], 'First paint fast'],
          ['Data resolves', 'await comments', 'The slow query finishes on the server.', [['stream', 'chunk 2', 'rsc payload']], [['Server', 'Comments ready']], ''],
          ['Swap', 'Replace Skeleton', 'The streamed chunk replaces the fallback; only the Client leaves hydrate.', [['hydration', 'LikeButton only', 'client']], [['Browser', 'Full page']], 'Page complete']
        ],
        presets: [['Server only', 'No JS shipped', 'async function Page(){ await db... }', '0 KB JS for this component'], ['Optimistic', 'Instant add', 'addOptimistic(todo)', 'UI updates before server reply']],
        pg: { title: 'Choose the Boundary', mission: 'Mark `LikeButton` as a client component by adding the directive at the top, and log "client leaf ready".', starter: '// LikeButton.jsx\n// add the correct directive here\nfunction LikeButton() {\n  const [n, setN] = React.useState(0);\n  console.log("client leaf ready");\n  return <button onClick={() => setN(n + 1)}>Likes: {n}</button>;\n}', solution: '"use client";\nfunction LikeButton() {\n  const [n, setN] = React.useState(0);\n  console.log("client leaf ready");\n  return <button onClick={() => setN(n + 1)}>Likes: {n}</button>;\n}', out: 'client leaf ready', hints: ['The directive is a string at the very top of the file.', 'It is spelled "use client".', 'Add "use client"; as the first statement.'], req: ['use client'], contains: ['client leaf ready'] },
        bug: { title: 'Hook in a Server Component', prompt: 'The build fails with an error about useState. Why?', code: '// app/page.jsx (no directive)\nexport default function Page() {\n  const [n, setN] = useState(0);\n  return <button onClick={() => setN(n+1)}>{n}</button>;\n}', opts: [['Server Components cannot use state or event handlers; move it to a "use client" component', 'Correct! Extract the interactive part.'], ['useState was renamed', 'It was not.'], ['export default is invalid', 'It is valid.']], ok: 0 },
        quiz: [['What ships to the browser for a Server Component?', ['Its full source', 'Only its rendered output', 'Its database credentials', 'Nothing, not even UI'], 1, 'The serialized result is sent, not the component code.'], ['What does Suspense enable on the server?', ['Caching', 'Progressive streaming of slow parts', 'Routing', 'Type checking'], 1, 'Fallbacks show while each boundary streams in.'], ['Where should filter/pagination state live?', ['Global store always', 'The URL', 'localStorage', 'A ref'], 1, 'URL state is shareable and survives refresh.']]
      })
    ]
  };
  return [master];
};

